python common/tools/bag_predictions.py model-v2x-track/bag-voxelrcnn-ros-g1v6awx --kit --variant tta12 --refresh --cache-dir $OUT/bag_bvrros6x_tta12 --out $OUT/predictions_bvrros6x_tta12.json
