python common/tools/pcdet_predict.py model-v2x-track/dsvt-ros-g1v6aw --ckpt model-v2x-track/dsvt-ros-g1v6aw/train/output/pcdet_model/run1/ckpt/checkpoint_epoch_40.pth --frames kit --postprocess model-v2x-track/dsvt-ros-g1v6aw/test/postprocess_tta.yaml --tta flip4+yaw+z --out $OUT/predictions_dsros6_tta.json
# member vrros6_tta12: model-v2x-track/voxelrcnn-ros-g1v6aw, checkpoint md5 92940549653ffdc30d9d64a2778c25cb
